(function() {
    'use strict';

    class CorpStructAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Derecho Comercial: Constitución de Empresa';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    descKey: 'r1_desc',
                    d1LabelKey: 'r1_d1_label',
                    d1Options: [
                        { value: 'sa', labelKey: 'r1_d1_opt_sa' },
                        { value: 'sas', labelKey: 'r1_d1_opt_sas' }
                    ],
                    d2LabelKey: 'r1_d2_label',
                    d2Options: [
                        { value: 'basic', labelKey: 'r1_d2_opt_basic' },
                        { value: 'moderate', labelKey: 'r1_d2_opt_moderate' },
                        { value: 'comprehensive', labelKey: 'r1_d2_opt_comprehensive' }
                    ]
                },
                {
                    titleKey: 'r2_title',
                    descKey: 'r2_desc',
                    d1LabelKey: 'r2_d1_label',
                    d1Options: [
                        { value: 'conservative', labelKey: 'r2_d1_opt_conservative' },
                        { value: 'balanced', labelKey: 'r2_d1_opt_balanced' },
                        { value: 'aggressive', labelKey: 'r2_d1_opt_aggressive' }
                    ],
                    d2LabelKey: 'r2_d2_label',
                    d2Options: [
                        { value: 'none', labelKey: 'r2_d2_opt_none' },
                        { value: 'basic', labelKey: 'r2_d2_opt_basic' },
                        { value: 'full', labelKey: 'r2_d2_opt_full' }
                    ]
                },
                {
                    titleKey: 'r3_title',
                    descKey: 'r3_desc',
                    d1LabelKey: 'r3_d1_label',
                    d1Options: [
                        { value: 'assembly_vote', labelKey: 'r3_d1_opt_assembly' },
                        { value: 'mediation', labelKey: 'r3_d1_opt_mediation' },
                        { value: 'partner_buyout', labelKey: 'r3_d1_opt_buyout' },
                        { value: 'veto_clause', labelKey: 'r3_d1_opt_veto' }
                    ],
                    d2LabelKey: 'r3_d2_label',
                    d2Options: [
                        { value: 'standard', labelKey: 'r3_d2_opt_standard' },
                        { value: 'enhanced', labelKey: 'r3_d2_opt_enhanced' }
                    ]
                },
                {
                    titleKey: 'r4_title',
                    descKey: 'r4_desc',
                    d1LabelKey: 'r4_d1_label',
                    d1Options: [
                        { value: 'maintain', labelKey: 'r4_d1_opt_maintain' },
                        { value: 'convert', labelKey: 'r4_d1_opt_convert' },
                        { value: 'restructure', labelKey: 'r4_d1_opt_restructure' }
                    ],
                    d2LabelKey: 'r4_d2_label',
                    d2Options: [
                        { value: 'organic', labelKey: 'r4_d2_opt_organic' },
                        { value: 'vc_funded', labelKey: 'r4_d2_opt_vc' },
                        { value: 'acquisition', labelKey: 'r4_d2_opt_acquisition' }
                    ]
                }
            ];
            // Session-stable RNG for the R2 aggressive-tax audit (see calculateResults).
            // Held on the adapter instance so an Undo→resubmit cannot "reroll" the outcome.
            this._r2AuditRoll = null;
        }

        // Robust language read: canonical `.language` first, then `.currentLanguage`,
        // then <html lang>, then 'en' (USF guide §9 / Lessons_Learned_USF_i18n_and_Modals).
        _lang() {
            try {
                var s = window.mySimulation;
                var l = (s && (s.language || s.currentLanguage))
                    || (document.documentElement && document.documentElement.lang) || 'en';
                return (String(l).toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
            } catch (e) { return 'en'; }
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 50000000,
                    annualCompliance: 0,
                    governance: 0,
                    investorReadiness: 0,
                    flexibility: 0,
                    structureType: '',
                    cashHistory: [],
                    governanceHistory: [],
                    investorHistory: [],
                    flexibilityHistory: [],
                    roundCostHistory: [],
                    taxPenaltyApplied: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: '',
                    decision2: ''
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var d1 = document.getElementById('decision1Select');
            var d2 = document.getElementById('decision2Select');
            if (d1) decisions.decision1 = d1.value;
            if (d2) decisions.decision2 = d2.value;
            if (!decisions.decision1) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_select_d1'), 'warning'
                );
                return false;
            }
            if (!decisions.decision2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_select_d2'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundCost = 0;
            var govDelta = 0;
            var invDelta = 0;
            var flexDelta = 0;
            var narrative = '';
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (period === 1) {
                if (d.decision1 === 'sa') {
                    ds.structureType = 'sa';
                    roundCost += 3000000;
                    ds.annualCompliance = 15000000;
                    govDelta += 60;
                    flexDelta += 30;
                    invDelta += 50;
                    narrative = t('r1_result_sa');
                } else {
                    ds.structureType = 'sas';
                    roundCost += 800000;
                    ds.annualCompliance = 6000000;
                    govDelta += 40;
                    flexDelta += 70;
                    invDelta += 30;
                    narrative = t('r1_result_sas');
                }
                if (d.decision2 === 'moderate') {
                    govDelta += 15;
                    roundCost += 2000000;
                } else if (d.decision2 === 'comprehensive') {
                    govDelta += 30;
                    roundCost += 5000000;
                }
            }

            if (period === 2) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'conservative') {
                    roundCost += 2000000;
                    govDelta += 5;
                    narrative = t('r2_result_conservative');
                } else if (d.decision1 === 'balanced') {
                    narrative = t('r2_result_balanced');
                } else if (d.decision1 === 'aggressive') {
                    roundCost -= 3000000;
                    govDelta -= 10;
                    // Session-stable audit roll: draw once, reuse thereafter so an
                    // Undo→resubmit cannot reroll the 30% audit risk (fairness/replay).
                    if (this._r2AuditRoll === null) { this._r2AuditRoll = Math.random(); }
                    var penalty = this._r2AuditRoll < 0.3;
                    if (penalty) {
                        roundCost += 10000000;
                        ds.taxPenaltyApplied = true;
                        narrative = t('r2_result_aggressive_penalty');
                    } else {
                        narrative = t('r2_result_aggressive_ok');
                    }
                }
                if (d.decision2 === 'basic') {
                    roundCost += 3000000;
                    invDelta += 20;
                } else if (d.decision2 === 'full') {
                    roundCost += 8000000;
                    invDelta += 40;
                    if (ds.structureType === 'sa') {
                        invDelta += 10;
                    } else {
                        invDelta -= 5;
                    }
                }
            }

            if (period === 3) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'assembly_vote') {
                    if (ds.structureType === 'sa') {
                        govDelta += 15;
                        flexDelta -= 10;
                    } else {
                        govDelta += 5;
                        flexDelta -= 5;
                        roundCost += 1000000;
                    }
                    narrative = t('r3_result_assembly');
                } else if (d.decision1 === 'mediation') {
                    govDelta += 10;
                    flexDelta += 5;
                    roundCost += 2000000;
                    narrative = t('r3_result_mediation');
                } else if (d.decision1 === 'partner_buyout') {
                    govDelta += 5;
                    flexDelta += 10;
                    roundCost += 15000000;
                    narrative = t('r3_result_buyout');
                } else if (d.decision1 === 'veto_clause') {
                    govDelta += 10;
                    flexDelta -= 15;
                    roundCost += 500000;
                    narrative = t('r3_result_veto');
                }
                if (d.decision2 === 'enhanced') {
                    govDelta += 10;
                    roundCost += 5000000;
                }
            }

            if (period === 4) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'maintain') {
                    flexDelta += 5;
                    narrative = t('r4_result_maintain');
                } else if (d.decision1 === 'convert') {
                    if (ds.structureType === 'sas') {
                        roundCost += 5000000;
                        govDelta += 20;
                        invDelta += 20;
                        flexDelta -= 20;
                        ds.annualCompliance = 15000000;
                        narrative = t('r4_result_convert_to_sa');
                    } else {
                        roundCost += 3000000;
                        govDelta -= 10;
                        invDelta -= 10;
                        flexDelta += 20;
                        ds.annualCompliance = 6000000;
                        narrative = t('r4_result_convert_to_sas');
                    }
                } else if (d.decision1 === 'restructure') {
                    roundCost += 8000000;
                    govDelta += 10;
                    invDelta += 10;
                    flexDelta += 10;
                    narrative = t('r4_result_restructure');
                }
                if (d.decision2 === 'organic') {
                    roundCost += 2000000;
                    govDelta += 5;
                    invDelta += 5;
                    flexDelta += 5;
                } else if (d.decision2 === 'vc_funded') {
                    if (ds.investorReadiness + invDelta >= 60) {
                        // COP $30.000M (30 billion) VC round per Concept §7 / narrative "$30B".
                        ds.cash += 30000000000;
                        invDelta += 15;
                        narrative += '<br>' + t('r4_vc_success');
                    } else {
                        roundCost += 3000000;
                        narrative += '<br>' + t('r4_vc_fail');
                    }
                } else if (d.decision2 === 'acquisition') {
                    if (ds.governance + govDelta >= 70) {
                        // COP $80.000M (80 billion) enterprise value per Concept §7 / narrative "$80B".
                        ds.cash += 80000000000;
                        govDelta += 10;
                        narrative += '<br>' + t('r4_acq_success');
                    } else {
                        roundCost += 5000000;
                        narrative += '<br>' + t('r4_acq_fail');
                    }
                }
            }

            ds.cash -= roundCost;
            ds.governance = Math.max(0, Math.min(100, ds.governance + govDelta));
            ds.investorReadiness = Math.max(0, Math.min(100, ds.investorReadiness + invDelta));
            ds.flexibility = Math.max(0, Math.min(100, ds.flexibility + flexDelta));

            ds.cashHistory.push(ds.cash);
            ds.governanceHistory.push(ds.governance);
            ds.investorHistory.push(ds.investorReadiness);
            ds.flexibilityHistory.push(ds.flexibility);
            ds.roundCostHistory.push(roundCost);

            // Advance the briefing/decision panel to the NEXT round.
            // NOTE: `period` is captured above BEFORE the framework increments
            // state.currentPeriod, so nextPeriod is exactly period+1. (The prior
            // code read `state.currentPeriod + 1` inside the timeout, which fires
            // AFTER the increment and therefore skipped a round — off-by-one.)
            var self = this;
            var nextPeriod = period + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: period,
                decision1: d.decision1,
                decision2: d.decision2,
                roundCost: roundCost,
                governance: ds.governance,
                investorReadiness: ds.investorReadiness,
                flexibility: ds.flexibility,
                cash: ds.cash,
                narrative: narrative
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod',
                function(v) { return Math.min(v, 4); });   // defensive: never render "5 of 4"
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('complianceDisplay', 'domainState.annualCompliance',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('governanceDisplay', 'domainState.governance',
                function(v) { return v + '/100'; });
            uiManager.bind('investorDisplay', 'domainState.investorReadiness',
                function(v) { return v + '/100'; });
            uiManager.bind('flexibilityDisplay', 'domainState.flexibility',
                function(v) { return v + '/100'; });
            // Accessibility: give the two canvases a localized text alternative.
            var t = window.mySimulation.t.bind(window.mySimulation);
            var cc = document.getElementById('cashChart');
            if (cc) { cc.setAttribute('role', 'img'); cc.setAttribute('aria-label', t('chart_cash_aria')); }
            var mc = document.getElementById('metricsChart');
            if (mc) { mc.setAttribute('role', 'img'); mc.setAttribute('aria-label', t('chart_metrics_aria')); }
        }

        _fmtCurrency(v) {
            var a = Math.abs(v);
            if (a >= 1000000000) { return '$' + (v / 1000000000).toFixed(a >= 10000000000 ? 0 : 1) + 'B'; }
            if (a >= 1000000)    { return '$' + (v / 1000000).toFixed(0) + 'M'; }
            return '$' + Math.round(v).toLocaleString();
        }

        getChartConfig() {
            var isEs = (this._lang() === 'es');
            var self = this;
            var L = isEs ? {
                capitalTitle: 'Capital a lo Largo de las Rondas', capitalLabel: 'Capital (COP)',
                scoresTitle: 'Puntajes a lo Largo de las Rondas',
                gov: 'Gobernanza', inv: 'Preparación Inv.', flex: 'Flexibilidad'
            } : {
                capitalTitle: 'Capital Over Rounds', capitalLabel: 'Capital (COP)',
                scoresTitle: 'Scores Over Rounds',
                gov: 'Governance', inv: 'Investor Readiness', flex: 'Flexibility'
            };
            return {
                cashChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: L.capitalLabel,
                            data: [],
                            backgroundColor: 'rgba(26,107,60,0.7)',
                            borderColor: '#1a6b3c',
                            borderWidth: 2,
                            borderRadius: 3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: L.capitalTitle, color: '#1a2744', font: { size: 13, weight: 'bold' } },
                            legend: { display: false },
                            tooltip: { callbacks: { label: function(c) { return self._fmtCurrency(c.parsed.y); } } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#3d4f6a', callback: function(v) { return self._fmtCurrency(v); } } },
                            x: { grid: { display: false }, ticks: { color: '#3d4f6a' } }
                        }
                    }
                },
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L.gov,
                                data: [],
                                borderColor: '#2c3e6b',
                                backgroundColor: 'rgba(44,62,107,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#2c3e6b'
                            },
                            {
                                label: L.inv,
                                data: [],
                                borderColor: '#8a6d00',
                                backgroundColor: 'rgba(138,109,0,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#8a6d00'
                            },
                            {
                                label: L.flex,
                                data: [],
                                borderColor: '#2471a3',
                                backgroundColor: 'rgba(36,113,163,0.08)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#2471a3'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
