        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            // History rows are {decisions, results} — read the snapshotted `results`,
            // NOT `domainState` (which the framework does not attach to history rows).
            var last = history[history.length - 1];
            var r = (last && last.results) || {};
            var cash = (r.cash != null) ? r.cash : 0;
            var gov = (r.governance != null) ? r.governance : 0;
            var inv = (r.investorReadiness != null) ? r.investorReadiness : 0;
            var flex = (r.flexibility != null) ? r.flexibility : 0;
            var composite = Math.round((gov + inv + flex) / 3);
            var totalCost = history.reduce(function(s, h) {
                return s + (((h && h.results) || {}).roundCost || 0);
            }, 0);

            var isEs = (this._lang() === 'es');
            var L = isEs ? {
                expert: 'Experto', competent: 'Competente', developing: 'En Desarrollo',
                govStrong: 'Una estructura de gobierno sólida protege los derechos de los accionistas.',
                govWeak: 'La gobernanza sigue débil — los socios minoritarios podrían estar en riesgo.',
                invHigh: 'La empresa está bien posicionada para atraer capital de riesgo.',
                invLow: 'La preparación para inversionistas es baja — conseguir VC será difícil.',
                flexHigh: 'La flexibilidad corporativa permite adaptarse rápido a los cambios del mercado.',
                flexLow: 'La estructura es rígida — considera reestructurar para ganar agilidad.',
                insolvent: 'La empresa es insolvente. Los costos superaron el capital disponible.'
            } : {
                expert: 'Expert', competent: 'Competent', developing: 'Developing',
                govStrong: 'Strong governance structure protects shareholder rights.',
                govWeak: 'Governance remains weak — minority shareholders may be at risk.',
                invHigh: 'The company is well positioned to attract venture capital.',
                invLow: 'Investor readiness is low — VC funding will be challenging.',
                flexHigh: 'Corporate flexibility allows quick adaptation to market changes.',
                flexLow: 'The structure is rigid — consider restructuring for agility.',
                insolvent: 'The company is insolvent. Costs exceeded available capital.'
            };

            var performance = L.developing;
            if (composite >= 70 && cash > 30000000) performance = L.expert;
            else if (composite >= 50 && cash > 10000000) performance = L.competent;

            var insights = [];
            if (gov >= 70) insights.push(L.govStrong);
            if (gov < 50) insights.push(L.govWeak);
            if (inv >= 70) insights.push(L.invHigh);
            if (inv < 40) insights.push(L.invLow);
            if (flex >= 60) insights.push(L.flexHigh);
            if (flex < 30) insights.push(L.flexLow);
            if (cash < 0) insights.push(L.insolvent);

            return {
                compositeScore: composite,
                finalCash: cash,
                governance: gov,
                investorReadiness: inv,
                flexibility: flex,
                totalCost: totalCost,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (state.currentPeriod === 1 && results.governance < 50) {
                return t('hint_low_governance');
            }
            if (state.currentPeriod === 2 && state.domainState.taxPenaltyApplied) {
                return t('hint_tax_penalty');
            }
            if (state.currentPeriod === 3 && results.cash < 15000000) {
                return t('hint_low_cash');
            }
            if (state.currentPeriod === 3 && results.flexibility < 30) {
                return t('hint_low_flexibility');
            }
            if (results.narrative) {
                return results.narrative;
            }
            return null;
        }

