        _updateBriefing(state) {
            if (!window.mySimulation) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var maxP = this.ROUNDS.length;
            var cp = state.currentPeriod || 1;

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');

            // Completion state: once past the final round, show a "complete" briefing
            // and stop rebuilding the decision dropdowns (the modal/scorecard takes over).
            if (cp > maxP) {
                if (titleEl) titleEl.textContent = t('complete_title');
                if (textEl) textEl.innerHTML = t('complete_text');
                var d1c = document.getElementById('decision1Select'); if (d1c) d1c.innerHTML = '';
                var d2c = document.getElementById('decision2Select'); if (d2c) d2c.innerHTML = '';
                return;
            }

            var idx = Math.min(cp - 1, maxP - 1);
            var round = this.ROUNDS[idx];

            if (titleEl) titleEl.textContent = t(round.titleKey);
            if (textEl) textEl.innerHTML = t(round.descKey);

            var d1Label = document.getElementById('d1Label');
            if (d1Label) d1Label.textContent = t(round.d1LabelKey);

            var placeholder = t('select_placeholder');
            function buildOptions(selectEl, opts) {
                selectEl.innerHTML = '';
                var ph = document.createElement('option');
                ph.value = '';
                ph.textContent = placeholder;
                selectEl.appendChild(ph);
                opts.forEach(function(opt) {
                    var option = document.createElement('option');
                    option.value = opt.value;
                    option.textContent = t(opt.labelKey);
                    selectEl.appendChild(option);
                });
                selectEl.value = '';   // force a deliberate choice each round
            }

            var d1Select = document.getElementById('decision1Select');
            if (d1Select) buildOptions(d1Select, round.d1Options);

            var d2Label = document.getElementById('d2Label');
            if (d2Label) d2Label.textContent = t(round.d2LabelKey);

            var d2Select = document.getElementById('decision2Select');
            if (d2Select) buildOptions(d2Select, round.d2Options);

            var badge = document.getElementById('structureBadge');
            if (badge && window.mySimulation.state && window.mySimulation.state.domainState) {
                var st = window.mySimulation.state.domainState.structureType;
                if (st) {
                    badge.textContent = st.toUpperCase();
                    badge.style.display = 'inline-block';
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CorpStructAdapter(), {
            simulationType: 'corp_structure_522',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
